var i=[{title:`Statisch rekken`,text:`Een statische rekoefening houdt een spier of gewricht zachtjes vast nabij het einde van het comfortabele bereik. Een kuitrek tegen een muur of een ondersteunde rek van de heupbuiger kan bijvoorbeeld korte tijd worden vastgehouden zonder te veren. Het moet voelen als milde spanning, nooit als scherpe pijn of gevoelloosheid.`},{title:`Dynamisch rekken`,text:`Dynamisch rekken beweegt steeds opnieuw door een nuttig bereik: beenzwaaien die je kunt beheersen, armcirkels, wisselende lunges. Elke herhaling is bewust, niet veerkrachtig of gehaast. Deze oefeningen passen vanzelf in een warming-up voor hardlopen, tillen en sport.`},{title:`Wanneer je welke gebruikt`,text:`Voor een explosieve inspanning werken geleidelijke dynamische beweging en het oefenen van de oefening zelf meestal het best. Lang, intensief statisch rekken vlak ervoor kan kracht of vermogen kort verminderen, terwijl een paar korte houdtijden minder zorgwekkend zijn. Na de training of in een aparte sessie is statisch rekken een redelijke manier om aan flexibiliteit te werken.`},{title:`Hoeveel je doet`,text:`Gebruik korte, comfortabele houdtijden en herhaal ze over weken in plaats van in één sessie een nieuw bereik te forceren. Begin bij dynamische oefeningen met een klein bereik en vergroot het alleen zolang de beweging beheerst blijft. Rekken hoeft geen pijn te doen om te werken, en meer flexibiliteit helpt niet bij elke taak.`},{title:`Wat rekken niet kan beloven`,text:`Gebruik dynamische oefeningen om je voor te bereiden op actieve beweging en statische houdtijden als flexibiliteit het doel is. Geen van beide maakt je blessurebestendig of voorkomt betrouwbaar spierpijn. Houdt pijn aan, vraag dan een arts of fysiotherapeut om advies dat bij je past.`}];var t=[{label:`ACE 2026: praktische richtlijnen voor rekken`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE 2026: mobiliteit versus flexibiliteit`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`NHS: rustige cooling-down`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};